import itertools
pF, pB = {1: .3, 0: .7}, {1: .2, 0: .8}
pY1 = {(1, 1): .9, (1, 0): .6, (0, 1): .5, (0, 0): .1}
pR, pC = {1: .8, 0: .1}, {1: .7, 0: .05}
def J(f, b, y, r, c):
    py = pY1[f, b] if y else 1 - pY1[f, b]
    return pF[f] * pB[b] * py * (pR[y] if r else 1 - pR[y]) * (pC[y] if c else 1 - pC[y])
V = list(itertools.product([0, 1], repeat=5))              # (f, b, y, r, c)
P = lambda cond: sum(J(*v) for v in V if cond(*v))
print('P(R=1) =', round(P(lambda f, b, y, r, c: r == 1), 4))
print('P(F=1|Y=1) =', round(P(lambda f, b, y, r, c: f == 1 and y == 1) / P(lambda f, b, y, r, c: y == 1), 4))
print('sum over C of P(C|Y):', [pC[y] + (1 - pC[y]) for y in (0, 1)])
scopes = [{'F'}, {'B'}, {'F', 'B', 'Y'}, {'Y', 'R'}, {'Y', 'C'}]    # all five CPTs, no pruning
print('scope after eliminating Y:', sorted(set().union(*[s for s in scopes if 'Y' in s]) - {'Y'}))
print('scope after eliminating Y if barren C were pruned first:', sorted(set().union(*[s for s in scopes[:4] if 'Y' in s]) - {'Y'}))
